<?php
namespace App\Http\Controllers\Api\Website;
use App\Http\Controllers\Controller; use App\Http\Requests\Website\AddToCartRequest; use App\Http\Requests\Website\UpdateCartItemRequest; use App\Http\Resources\Website\CartItemResource; use App\Http\Resources\Website\CartResource; use App\Models\Cart; use App\Models\CartItem; use App\Models\Product; use App\Services\Files\SecureUploadService; use App\Services\Pricing\ProductPricingService; use App\Traits\ApiResponseTrait; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class CartController extends Controller {
 use ApiResponseTrait;
 public function __construct(private ProductPricingService $pricing){}
 private function getCurrentCart(): Cart { $user=request()->user(); abort_unless($user,401); return Cart::firstOrCreate(['user_id'=>$user->id],['subtotal'=>0,'total'=>0]); }
 public function index(Request $request){$cart=$this->getCurrentCart(); $this->syncCartPrices($cart); return $this->success(new CartResource($cart->fresh(['items.product','items.designFile'])),'تم جلب السلة بنجاح');}
 public function add(AddToCartRequest $request){return DB::transaction(function()use($request){$cart=Cart::where('user_id',$request->user()->id)->lockForUpdate()->first(); if(!$cart)$cart=Cart::create(['user_id'=>$request->user()->id,'subtotal'=>0,'total'=>0]); $product=Product::whereKey($request->integer('product_id'))->lockForUpdate()->firstOrFail(); $selection=$this->selection($request); $price=$this->pricing->calculate($product,$selection,$request->integer('quantity')); $hash=$this->pricing->hash($product,$selection); $item=CartItem::where('cart_id',$cart->id)->where('hash_key',$hash)->lockForUpdate()->first(); if($item){$newQty=(int)$item->quantity+$request->integer('quantity'); $price=$this->pricing->calculate($product,$selection,$newQty); $item->forceFill(['quantity'=>$newQty,'price_per_unit'=>$price['price_per_unit'],'line_total'=>$price['line_total'],'customization_snapshot'=>$price['customization'],'pricing_snapshot'=>$price['pricing_snapshot'],'note'=>$request->input('note',$item->note)])->save();}else{$item=CartItem::create(['cart_id'=>$cart->id,'product_id'=>$product->id,'note'=>$request->input('note'),'quantity_id'=>$request->input('quantity_id'),'quantity'=>$request->integer('quantity'),'price_per_unit'=>$price['price_per_unit'],'line_total'=>$price['line_total'],'is_sample'=>$request->boolean('is_sample'),'hash_key'=>$hash,'customization_snapshot'=>$price['customization'],'pricing_snapshot'=>$price['pricing_snapshot']]);} $this->recalculateCart($cart); return $this->success(new CartItemResource($item->fresh(['product','designFile'])),'تمت الإضافة إلى السلة');},3);}
 public function update(CartItem $cartItem,UpdateCartItemRequest $request){$this->authorizeCartItem($cartItem,$request); return DB::transaction(function()use($cartItem,$request){$item=CartItem::whereKey($cartItem->id)->lockForUpdate()->firstOrFail(); $product=Product::whereKey($item->product_id)->lockForUpdate()->firstOrFail(); $selection=array_merge((array)$item->customization_snapshot,$this->selection($request,true)); $qty=$request->has('quantity')?$request->integer('quantity'):(int)$item->quantity; $price=$this->pricing->calculate($product,$selection,$qty); $hash=$this->pricing->hash($product,$selection); $conflict=CartItem::where('cart_id',$item->cart_id)->where('hash_key',$hash)->whereKeyNot($item->id)->lockForUpdate()->first(); if($conflict) throw \Illuminate\Validation\ValidationException::withMessages(['cart'=>'يوجد عنصر آخر بنفس التخصيص؛ احذفه أو عدل الكمية منه.']); $item->forceFill(['quantity'=>$qty,'note'=>$request->input('note',$item->note),'quantity_id'=>$request->input('quantity_id',$item->quantity_id),'is_sample'=>$request->has('is_sample')?$request->boolean('is_sample'):$item->is_sample,'price_per_unit'=>$price['price_per_unit'],'line_total'=>$price['line_total'],'hash_key'=>$hash,'customization_snapshot'=>$price['customization'],'pricing_snapshot'=>$price['pricing_snapshot']])->save(); $this->recalculateCart($item->cart); return $this->success(new CartResource($item->cart->fresh(['items.product','items.designFile'])),'تم تحديث العنصر بنجاح');},3);}
 public function remove(CartItem $cartItem,Request $request){$this->authorizeCartItem($cartItem,$request); return DB::transaction(function()use($cartItem){$item=CartItem::whereKey($cartItem->id)->lockForUpdate()->firstOrFail();$cart=$item->cart;$item->delete();$this->recalculateCart($cart);return $this->success(new CartResource($cart->fresh(['items.product','items.designFile'])),'تم حذف العنصر من السلة');},3);}
 public function clear(Request $request){$cart=$this->getCurrentCart(); DB::transaction(function()use($cart){$locked=Cart::whereKey($cart->id)->lockForUpdate()->firstOrFail();$locked->items()->delete();$locked->update(['subtotal'=>0,'total'=>0]);},3);return $this->success(null,'تم تفريغ السلة');}
 public function uploadImage(Request $request,SecureUploadService $uploads){$request->validate(['image'=>'required_without:img|file','img'=>'required_without:image|file','cart_item_id'=>'required|integer|exists:cart_items,id']);$item=CartItem::whereKey($request->integer('cart_item_id'))->whereHas('cart',fn($q)=>$q->where('user_id',$request->user()->id))->firstOrFail();$file=$request->file('image')?:$request->file('img');$record=$uploads->storeDesign($file,$request->user()->id);$item->forceFill(['design_file_id'=>$record->id,'image_design'=>null])->save();return $this->success(new CartItemResource($item->fresh(['product','designFile'])),'تم رفع التصميم بنجاح');}
 private function authorizeCartItem(CartItem $item,Request $request):void{abort_unless($item->cart()->where('user_id',$request->user()->id)->exists(),403,'هذا العنصر لا يخص سلتك');}
 private function selection(Request $request,bool $partial=false):array{$keys=['size_id','color_id','material_id','printing_method_id','design_service_id','quantity_id','print_locations','embroider_locations','selected_options','is_sample'];$out=[];foreach($keys as $k){if(!$partial||$request->exists($k))$out[$k]=$k==='is_sample'?$request->boolean($k):$request->input($k);}return $out;}
 private function recalculateCart(Cart $cart):void{$subtotal=round((float)$cart->items()->sum('line_total'),4);$cart->forceFill(['subtotal'=>$subtotal,'total'=>max(0,$subtotal)])->save();}
 private function syncCartPrices(Cart $cart):void{DB::transaction(function()use($cart){$locked=Cart::whereKey($cart->id)->lockForUpdate()->firstOrFail();$items=$locked->items()->with('product')->lockForUpdate()->get();foreach($items as $item){if(!$item->product||$item->product->trashed()||(int)$item->product->status_id!==1)continue;$price=$this->pricing->calculate($item->product,(array)$item->customization_snapshot,(int)$item->quantity);if(bccomp((string)$item->price_per_unit,(string)$price['price_per_unit'],4)!==0||bccomp((string)$item->line_total,(string)$price['line_total'],4)!==0)$item->forceFill(['price_per_unit'=>$price['price_per_unit'],'line_total'=>$price['line_total'],'pricing_snapshot'=>$price['pricing_snapshot']])->save();}$this->recalculateCart($locked);},3);}
}
